package edu.hfut.access.service;
import java.util.*;import java.time.*;import java.util.regex.*;import org.springframework.stereotype.Component;import edu.hfut.access.dto.Context;import static edu.hfut.access.security.Identity.text;
@Component public class AccessPolicy{
 public static final List<String> GATES=Arrays.asList("东门","南门","西门","北门");
 public static final List<String> METHODS=Arrays.asList("校园卡","工号","人脸识别","车牌识别","预约二维码","校友二维码","二维码扫码","人工核验","人工核验后放行","现场放行");
 public static final Map<String,String> LABELS=new LinkedHashMap<>();static{String[]r={"student","teacher","visitor","alumni","guard","admin"},l={"学生","教职工","访客","校友","门岗安保","保卫处管理员"};for(int i=0;i<r.length;i++)LABELS.put(r[i],l[i]);}
 public static List<String> list(Object o){if(o instanceof List){List<String>r=new ArrayList<>();for(Object x:(List<?>)o)r.add(String.valueOf(x));return r;}List<String>r=new ArrayList<>();if(o!=null)for(String x:String.valueOf(o).split("[、,，/]"))if(!x.trim().isEmpty())r.add(x.trim());return r;}
 public static Long timestamp(String s){try{if(s==null||s.isEmpty())return null;String t=s.replaceFirst(" ","T");try{return OffsetDateTime.parse(t).toInstant().toEpochMilli();}catch(Exception e){}return LocalDateTime.parse(t.length()==16?t+":00":t).atZone(ZoneId.of("Asia/Shanghai")).toInstant().toEpochMilli();}catch(Exception e){return null;}}
 public static boolean time(String range){return time(range,LocalTime.now(ZoneId.of("Asia/Shanghai")));}
 /** P4-C approved safety change: full parse and bounded hours; never fail open. */
 public static boolean time(String range,LocalTime t){if(range==null||t==null)return false;if(Arrays.asList("全天","全天时间","预约时段","预约时段内").contains(range))return true;Matcher m=Pattern.compile("([01]\\d|2[0-3]):([0-5]\\d)-([01]\\d|2[0-3]):([0-5]\\d)").matcher(range);if(!m.matches())return false;int a=Integer.parseInt(m.group(1))*60+Integer.parseInt(m.group(2)),b=Integer.parseInt(m.group(3))*60+Integer.parseInt(m.group(4)),now=t.getHour()*60+t.getMinute();return a<=b?now>=a&&now<=b:now>=a||now<=b;}
 public static class Decision{public boolean allowed;public String reason="",method;public Map<String,Object> person,gate,rule,vehicle;public Decision deny(String r){reason=r;allowed=false;return this;}}
 public Decision decide(Context c,Map<String,Object>qr,String kind,String gateName,String method,List<Map<String,Object>>gates,List<Map<String,Object>>rules,Map<String,Object>settings,String safetyReason){
  Decision d=new Decision();d.person=c.person;d.vehicle=c.vehicle;boolean isQr=Arrays.asList("qr","visitorQr","alumniQr").contains(kind);d.method=method==null||method.isEmpty()?(isQr?"二维码扫码":"plate".equals(kind)?"车牌识别":"face".equals(kind)?"人脸识别":"campusCard".equals(kind)?"校园卡":"身份核验"):method;
  if(isQr){if(qr==null)return d.deny("未找到有效二维码");if(!"有效".equals(qr.get("status")))return d.deny("二维码状态不可用");Long a=timestamp(text(qr,"validFrom")),b=timestamp(text(qr,"validTo"));if(a==null||b==null)return d.deny("二维码有效期不正确");if(a>System.currentTimeMillis())return d.deny("二维码尚未到可用时间");if(b<System.currentTimeMillis())return d.deny("二维码已过期");}
  if("plate".equals(kind)){if(c.vehicle==null)return d.deny("未找到绑定车辆");if(!"正常".equals(c.vehicle.get("status")))return d.deny("车辆状态"+text(c.vehicle,"status"));}
  if(c.person==null)return d.deny(isQr?"二维码未绑定有效人员":"未找到有效人员信息");
  String status=text(c.person,"status");if(!Arrays.asList("正常","在线","值守中","已认证").contains(status)||Boolean.FALSE.equals(c.person.get("accountEnabled")))return d.deny("人员状态不可用");
  if("face".equals(kind)&&!c.faceAvailable)return d.deny("未上传可用人脸照片");if(safetyReason!=null&&!safetyReason.isEmpty())return d.deny(safetyReason);
  for(Map<String,Object> g:gates)if(gateName.equals(g.get("id"))||gateName.equals(g.get("name"))){d.gate=g;break;}if(d.gate==null)return d.deny("校门不存在");if(!"开放".equals(d.gate.get("status")))return d.deny("校门"+text(d.gate,"status"));String hours=text(d.gate,"openTime");if(hours.isEmpty())hours=text(settings,"gateOpenTime")+"-"+text(settings,"gateCloseTime");if(!time(hours))return d.deny("当前不在校门开放时间内");
  String role=LABELS.getOrDefault(text(c.person,"role"),text(c.person,"role"));for(Map<String,Object> r:rules)if((role.equals(r.get("role"))||role.equals("保卫处管理员")&&"管理员".equals(r.get("role")))&&"启用".equals(r.get("status"))){d.rule=r;break;}if(d.rule==null)return d.deny("未配置该角色通行规则");
  List<String> allowedGates=list(d.rule.get("gates"));if(!allowedGates.contains("全部校门")&&!allowedGates.contains("值守校门")&&!allowedGates.contains(text(d.gate,"name"))&&!allowedGates.contains(text(d.gate,"id")))return d.deny("该角色不允许从此校门通行");
  List<String> candidates=new ArrayList<>(Collections.singletonList(d.method));if(d.method.equals("校园卡"))candidates.add("工号");if(d.method.equals("工号"))candidates.add("校园卡");if(d.method.contains("二维码"))candidates.add("二维码扫码");if(qr!=null){if("visitor".equals(qr.get("type")))candidates.add("预约二维码");if("alumni".equals(qr.get("type")))candidates.add("校友二维码");}boolean match=false;for(String s:list(d.rule.get("methods")))for(String v:candidates)if(!v.isEmpty()&&(v.contains(s)||s.contains(v)))match=true;if(!match)return d.deny("该角色不允许使用此通行方式");if(!time(text(d.rule,"allowedTime")))return d.deny("当前不在该角色允许通行时间内");d.allowed=true;return d;
 }
}
